import java.util.*;
import java.io.*;

public class Main {
    static final long INF = 100000000000000000L;
    static final int MAX_N = 1001;
    static int[] dx = {0, 0, -1, 1};
    static int[] dy = {-1, 1, 0, 0};
    static List<Integer>[] graph = new ArrayList[MAX_N * 100]; // size estimate
    static boolean[] visited = new boolean[MAX_N * 100];
    static int[] match = new int[MAX_N * 100];

    static boolean is_valid_cell(int x, int y, String[] grid) {
        int n = grid.length;
        return x >= 0 && y >= 0 && x < n && y < n && grid[x].charAt(y) != 'Y' && grid[x].charAt(y) != 'Z';
    }

    static long[][] bfs_distance(int start_x, int start_y, String[] grid) {
        int n = grid.length;
        long[][] dist = new long[n][n];
        for (long[] row : dist) Arrays.fill(row, INF);
        dist[start_x][start_y] = 0;
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{start_x, start_y});
        while (!q.isEmpty()) {
            int[] cell = q.pollFirst();
            int cx = cell[0], cy = cell[1];
            for (int dir = 0; dir < 4; dir++) {
                int nx = cx + dx[dir], ny = cy + dy[dir];
                if (!is_valid_cell(nx, ny, grid) || dist[nx][ny] != INF) continue;
                dist[nx][ny] = dist[cx][cy] + 1;
                q.offer(new int[]{nx, ny});
            }
        }
        return dist;
    }

    static void read_input_and_build_graph(Scanner sc, String[] s1, String[] s2, int n, int t) {
        int rx = -1, ry = -1;
        for (int i = 0; i < n; i++) {
            s1[i] = sc.next();
        }
        for (int i = 0; i < n; i++) {
            s2[i] = sc.next();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (s1[i].charAt(j) == 'Z') {
                    rx = i;
                    ry = j;
                }
            }
        }
        long[][] reac_dist = bfs_distance(rx, ry, s1);
        int sizeEstimate = n * n * 10; // rough estimate for graph size
        for (int i = 0; i < sizeEstimate; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!is_valid_cell(i, j, s1)) continue;
                long[][] from_cell = bfs_distance(i, j, s1);
                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        if (!is_valid_cell(x, y, s1)) continue;
                        if (from_cell[x][y] > t || from_cell[x][y] > reac_dist[x][y]) continue;
                        if (from_cell[x][y] == reac_dist[x][y]) {
                            boolean can_move = false;
                            for (int dir_idx = 0; dir_idx < 4; dir_idx++) {
                                int xto = x + dx[dir_idx];
                                int yto = y + dy[dir_idx];
                                if (!is_valid_cell(xto, yto, s1)) continue;
                                if (from_cell[xto][yto] >= reac_dist[xto][yto]) continue;
                                can_move = true;
                            }
                            if (!can_move) continue;
                        }
                        int max_num1 = s1[i].charAt(j) - '0';
                        int max_num2 = s2[x].charAt(y) - '0';
                        for (int num1 = 1; num1 <= max_num1; num1++) {
                            for (int num2 = 1; num2 <= max_num2; num2++) {
                                int v1 = 10 * (j + i * 10) + num1;
                                int v2 = 10 * (y + 10 * x) + num2;
                                graph[v1].add(v2);
                            }
                        }
                    }
                }
            }
        }
    }

    static boolean match_vertex(int v) {
        if (visited[v]) return false;
        visited[v] = true;
        for (int to : graph[v]) {
            if (match[to] == 0 || match_vertex(match[to])) {
                match[to] = v;
                return true;
            }
        }
        return false;
    }

    static void solve_problem(Scanner sc) {
        int n = sc.nextInt();
        int t = sc.nextInt();
        String[] s1 = new String[n];
        String[] s2 = new String[n];
        read_input_and_build_graph(sc, s1, s2, n, t);
        int totalNodes = MAX_N * 100; // size estimate
        int totalMatches = 0;
        for (int i = 0; i < totalNodes; i++) {
            Arrays.fill(visited, false);
            match_vertex(i);
        }
        for (int i = 0; i < totalNodes; i++) {
            if (match[i] != 0) totalMatches++;
        }
        System.out.println(totalMatches);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        solve_problem(sc);
        sc.close();
    }
}
